def add(kind,kn,stem,ex,hints,diff=2,cw='Calculate',**more):
 n=sum(i['source']['type']=='generated' for i in items)+1
 items.append(dict(id=f'9702-4.3-i{n:02}',kcs=[K(x) for x in kn],kind=kind,difficulty=diff,command_word=cw,source={'type':'generated'},stem=stem,marks=more.pop('marks',1),explanation=ex,hints=hints,**more))
def ans(v,u):return {'value':round(v,10),'unit':u,'sf_ok':[2,3]}
def templ(kn,stem,params,derived,formula,unit,wrong,ex,hints,diff=3,constraints=()):
 def ev(s,e):return eval(s,{'__builtins__':{},'abs':abs},e)
 nominal=None
 for vals in product(*(p['choices'] for p in params.values())):
  e=dict(zip(params,vals))
  for name,expr in derived.items():e[name]=ev(expr,e)
  if not all(ev(x,e) for x in constraints):continue
  a=ev(formula,e)
  assert a>0
  for x,_ in wrong:assert abs(ev(x,e)-a)>0.02*a,(e,x)
  if nominal is None:nominal=e
 assert nominal
 a=ev(formula,nominal)
 add('numeric',kn,stem,ex,hints,diff,answer=ans(a,unit),distractors=[{'value':round(ev(x,nominal),10),'misconception':m} for x,m in wrong],template={'params':params,'derived':derived,'answer':formula,'distractors':[{'expr':x,'misconception':m} for x,m in wrong],'constraints':list(constraints)})
# Three variants each; coupled KC questions provide cross checks.
