add('short',[1],'Define density.', 'Density is mass per unit volume: $\\rho=m/V$, measured in kg m$^{-3}$.',['Think of mass and volume.','State the ratio rather than a comparison between objects.','Begin “mass per unit…”'],cw='Define',rubric=[{'point':'Mass per unit volume.','keywords':[['mass'],['per unit volume','divided by volume']]}])
add('short',[2],'Define pressure.', 'Pressure is normal force per unit area: $p=F/A$, measured in pascals.',['Think of force and contact area.','Specify the force direction relative to the surface.','Begin “normal force per unit…”'],cw='Define',rubric=[{'point':'Normal force per unit area.','keywords':[['force'],['per unit area','divided by area']]}])
add('short',[3],'Show that a liquid column of density $\\rho$, cross-sectional area $A$ and height $\\Delta h$ produces $\\Delta p=\\rho g\\Delta h$.','The column mass is $\\rho A\\Delta h$, its weight is $\\rho A\\Delta h g$, and dividing by $A$ gives $\\Delta p=\\rho g\\Delta h$.',['Begin with a column of fluid.','Express its volume and mass before its weight.','Write $V=A\\Delta h$.'],4,'Show (that)',marks=3,rubric=[{'point':'Column volume is $A\\Delta h$ and mass is $\\rho A\\Delta h$.','keywords':[['rho','density'],['A'],['height','delta h','Δh']]},{'point':'Column weight is $\\rho A\\Delta h g$.','keywords':[['weight','force'],['g']]},{'point':'Divide weight by area to obtain pressure difference $\\rho g\\Delta h$.','keywords':[['pressure'],['area','A'],['rho g','ρg']]}])
