work(1,'A sample has mass 1.80 kg and volume $7.50\\times10^{-4}$ m$^3$. Calculate its density.',[('State $\\rho=m/V$.','Density is mass per unit volume.',None,''),('Substitute $1.80/(7.50\\times10^{-4})$.','Both quantities are already in SI units.',None,''),('Obtain $2.40\\times10^3$ kg m$^{-3}$.','The unit is mass divided by volume.',1.8/0.00075,'kg m^-3')],'A sample has mass 2.00 kg and volume $8.00\\times10^{-4}$ m$^3$. Calculate its density.',(2/0.0008,'kg m^-3'))
work(2,'A 36.0 N normal force acts over $0.0120$ m$^2$. Calculate pressure.',[('State $p=F/A$.','Pressure uses normal force per unit area.',None,''),('Substitute $36.0/0.0120$.','Use the contact area in square metres.',None,''),('Obtain $3.00\\times10^3$ Pa.','A pascal is a newton per square metre.',36/.012,'Pa')],'A 42.0 N force acts over $0.0140$ m$^2$. Calculate pressure.',(42/.014,'Pa'))
