work(4,'Calculate the pressure increase over 0.250 m in water of density 1000 kg m$^{-3}$.',[('State $\\Delta p=\\rho g\\Delta h$.','This is a pressure difference, so use the separation in depth.',None,''),('Substitute $1000\\times9.81\\times0.250$.','Use water density and SI depth.',None,''),('Obtain $2.45\\times10^3$ Pa.','Round to three significant figures.',1000*g*.25,'Pa')],'Calculate the pressure increase over 0.300 m in a liquid of density 850 kg m$^{-3}$.',(850*g*.3,'Pa'))
work(6,'A block displaces $1.50\\times10^{-3}$ m$^3$ of water of density 1000 kg m$^{-3}$. Calculate upthrust.',[('State $U=\\rho_f gV_{displaced}$.','Use fluid density and displaced volume.',None,''),('Substitute $1000\\times9.81\\times1.50\\times10^{-3}$.','The displaced water has this weight.',None,''),('Obtain 14.7 N.','The upthrust equals displaced fluid weight.',1000*g*.0015,'N')],'An object displaces $2.00\\times10^{-3}$ m$^3$ of oil of density 800 kg m$^{-3}$. Calculate upthrust.',(800*g*.002,'N'))
flash=[dict(id=f'fc{n}',kc=K(n),front=q,back=a) for n,q,a in [(1,'Define density.','Mass per unit volume; $\\rho=m/V$.'),(2,'Define pressure.','Normal force per unit area; $p=F/A$.'),(3,'State the hydrostatic pressure equation.','$\\Delta p=\\rho g\\Delta h$, with $\\rho$ the fluid density and $\\Delta h$ the vertical depth difference.'),(5,'State the origin of upthrust.','Hydrostatic pressure is greater at the lower surface, so the upward pressure force exceeds the downward pressure force.'),(6,'State Archimedes’ principle.','Upthrust equals the weight of fluid displaced: $F=\\rho gV$.')]]
pack=dict(subtopic='9702-4.3',spec='9702',version=1,note='Subjects/9702 Physics/04 Forces, density and pressure/4.3 Density and pressure.md',outline='Density is mass per unit volume, $\\rho=m/V$. Pressure is normal force per unit area, $p=F/A$. A fluid column of area $A$ and depth $\\Delta h$ has weight $\\rho A\\Delta h g$, so $\\Delta p=\\rho g\\Delta h$. Pressure rises with depth; the lower face of an immersed object receives a greater force than its upper face. This difference is upthrust, equal to the weight of displaced fluid: $F=\\rho gV$. For floating equilibrium, upthrust equals the object weight.',misconceptions=mis,worked=worked,items=items,flashcards=flash,diagrams=[])
